e\n                .dispatch(\"goods/purchase/details\", data)\n                .then((response) => {\n                    let data = JSON.parse(JSON.stringify(response.data));\n                    self.data = data;\n                    self.loading = false;\n                })\n                .catch((error) => {\n                    self.data = null;\n                    self.msg = self.getMsg(error);\n                    self.loading = false;\n                });\n        },\n        update() {\n            this.type = type;\n            switch (type) {\n                case \"Shipping\":\n                    let xData = this.shippingData;\n                    let yData = this.data;\n                    for (const x of xData) {\n                        if (x.unit && x.id === yData.id) {\n                            this.data.unit = x.unit;\n                        }\n                    }\n                    break;\n            }\n        },\n        open(type, item) {\n            this.clear();\n            this.resetScanner();\n            this.dialog = true;\n            this.type = type;\n            switch (type) {\n                case \"Shipping\":\n                    this.title = `${this.$t(\"shipping\")}${this.$t(\"scanner\")}`;\n                    if (item && \"barcode\" in item) {\n                        this.barcode = item.barcode;\n                        this.fetchItemDetails();\n                    }\n                    break;\n                case \"Search\":\n                    this.title = `${this.$t(\"search\")}${this.$t(\"scanner\")}`;\n                    break;\n                case \"StockTake\":\n                    this.title = `${this.$t(\"stocktake\")}`;\n                    break;\n            }\n            return new Promise((resolve, reject) => {\n                this.resolve = resolve;\n                this.reject = reject;\n            });\n        },\n        closeDialog(result) {\n            if (this.resolve) {\n                this.resolve(result);\n                this.resolve = null;\n                this.reject = null;\n            }\n            this.dialog = false;\n        },\n        confirm() {\n            if (this.data) {\n                switch (this.type) {\n                    case \"Shipping\":\n                        this.$store.dispatch(\"goods/shipping/add\", {\n                            data: { ...this.data, unit: this.unit },\n                        });\n                        break;\n                    case \"Search\":\n                        this.$router.push({\n                            name: \"GoodsDetails\",\n                            params: { id: this.data.goods.id },\n                        });\n                        break;\n                    case \"StockTake\":\n                        this.$router.push({\n                            name: \"StockTake\",\n                            params: { id: this.data.id },\n                        });\n                        break;\n                }\n            }\n            this.closeDialog(true);\n        },\n        cancel() {\n            this.closeDialog(false);\n        },\n        onDecode(a, b, c) {\n            // console.log(a, b, c);\n            const decoded = (a || \"\").trim().toUpperCase();\n\n            // Keep the first accepted barcode until user clears it manually.\n            if (!decoded || this.loading || this.barcode) {\n                return;\n            }\n\n            if (!this.isLikelyItemBarcode(decoded)) {\n                return;\n            }\n\n            this.msg = null;\n            this.barcode = decoded;\n            switch (this.type) {\n                case \"Shipping\":\n                    this.fetchItemDetails();\n                    break;\n                case \"Search\":\n                    this.fetchItemDetails();\n                    break;\n                case \"StockTake\":\n                    this.fetchPurchaseDetails();\n              