// import axios from "axios";
import { i18n } from "../../plugins";
import router from "../../router";
import axios from "../../utils/myAxios";

const endpoint = "/api/goods/purchase/stocktake/";
const name = "goods/purchase/stocktake";

export default {
    [`${name}/create`]({ commit, dispatch }, payload) {
        return new Promise((resolve, reject) => {
            axios
                .post(`${endpoint}create`, payload)
                .then(function(response) {
                    if (!response.data.error) {
                        dispatch("snackbar/show", {
                            color: "success",
                            text: i18n.t("snackbar.success.created")
                        });
                        resolve(response);
                    } else {
                        dispatch("snackbar/show", {
                            color: "error",
                            text: i18n.t("snackbar.fail.create")
                        });
                        reject(response);
                    }
                })
                .catch(function(error) {
                    if (!error.response) {
                        reject(error);
                        return;
                    }
                    let status = error.response.status;
                    switch (status) {
                        case 401:
                            dispatch("snackbar/show", {
                                color: "success",
                                text: i18n.t("snackbar.fail.token")
                            });
                            dispatch("auth/logout");
                            router.push({ name: "Login" });
                            break;
                    }
                    dispatch("snackbar/show", {
                        color: "error",
                        text: i18n.t("snackbar.fail.create")
                    });

                    reject(error);
                });
        });
    }
};
